// Package webclient embeds the browser client for the Windows host (the macOS host uses the
// Swift table generated by scripts/embed-webclient.py from the same files).
package webclient

import (
	"embed"
	"path"
)

//go:embed index.html client.js gestures.js style.css
var files embed.FS

// Asset is one file of the web client.
type Asset struct {
	ContentType string
	Body        []byte
}

var contentTypes = map[string]string{
	".html": "text/html; charset=utf-8",
	".js":   "text/javascript; charset=utf-8",
	".css":  "text/css; charset=utf-8",
	".svg":  "image/svg+xml",
}

// Files is the fixed asset table: name -> asset. Nothing else is ever served.
var Files = func() map[string]Asset {
	entries, err := files.ReadDir(".")
	if err != nil {
		panic(err)
	}
	table := make(map[string]Asset, len(entries))
	for _, e := range entries {
		body, err := files.ReadFile(e.Name())
		if err != nil {
			panic(err)
		}
		table[e.Name()] = Asset{ContentType: contentTypes[path.Ext(e.Name())], Body: body}
	}
	return table
}()
